'use strict';
function evidenceSummary(){let t=totals(state.filtered),by=buckets(state.filtered,r=>r[0]),ys=[...by.keys()].sort(),first=by.get(ys[0]),last=by.get(ys.at(-1)),change=ys.length>1&&first.mortos?100*(last.mortos/first.mortos-1):null;let nat=EXPOSICAO.sensitivity.sem_nao_simulavel.terms.find(t=>t.term==='concessao');let cards=[{big:N(t.mortos)+' mortes registradas',text:change==null?`${N(t.n)} sinistros no recorte; ${N(t.n?100*t.fatais/t.n:0,2)}% com morte.`:`Entre ${ys[0]} e ${ys.at(-1)}, mortes registradas ${change>=0?'aumentaram':'diminuíram'} ${N(Math.abs(change),1)}% neste recorte. Variação da contagem não é variação do risco por viagem.`,scope:'DESCRIÇÃO · acompanha os filtros'},{big:'Há persistência territorial',text:`Correlação de ${N(PERSISTENCIA.rho,2)} entre mortes nos dois biênios. Ajuda a selecionar locais para investigação; não demonstra ausência de ação ou falha do PDCA.`,scope:'ANÁLISE NACIONAL FIXA · intervalos com registros'},{big:'A comparação é sensível',text:`A associação ajustada de concessão com mortes tem IC que inclui 1 ao excluir não simuláveis: IRR ${N(nat.irr,2)} [${N(nat.low,2)}; ${N(nat.high,2)}]. Não há conclusão causal sobre governança.`,scope:'MODELO NACIONAL FIXO · exposição PNCT modelada'}];$('#opening-insights').innerHTML=cards.map(c=>`<div class="finding"><small>${c.scope}</small><b>${c.big}</b><p>${c.text}</p></div>`).join('');let sev=buckets(state.filtered,r=>REGISTROS.cats.gravidade[r[10]]);$('#severity-values').innerHTML=[...sev].map(([name,v])=>`<div><span>${esc(name)}</span><b>${N(v.n)} · ${N(t.n?100*v.n/t.n:0,1)}%</b></div>`).join('')||'Sem ocorrências no recorte.';}
const storyOverview=overview;overview=function(){storyOverview();evidenceSummary()};
function theoryContext(){let t=totals(state.filtered);$('#theory-context').innerHTML=`<b>Seu recorte empírico: ${esc(labels())}</b><p>${N(t.n)} sinistros e ${N(t.mortos)} mortes registradas. Os filtros alteram este resumo e a exploração nas outras páginas; a fundamentação teórica e os modelos nacionais não são reestimados por eles.</p>`}
const storyRender=render;render=function(){storyRender();if(state.page==='teoria')theoryContext();if(state.page==='padroes')multinomialView()};
const storyPage=page;page=function(id){storyPage(id);if(id==='teoria'){$('.filters').style.opacity='1';$$('.filters select').forEach(e=>e.disabled=false);$('#export').style.display='block';$('#scope').textContent=labelsForScope();theoryContext()}};
const corridors=[...new Set(RODOVIAS.map(r=>r.uf+'|'+r.br))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));for(let k of corridors){let [u,b]=k.split('|');$('#map-corridor').add(new Option(u+' · BR-'+b.padStart(3,'0'),k))}
$('#map-corridor').onchange=()=>{let k=$('#map-corridor').value;if(k==='all')return;let[u,b]=k.split('|');$('#uf').value=String(REGISTROS.cats.uf.indexOf(u));$('#br').value=b;filter()};$('#map-reset-view').onclick=()=>{$('#uf').value='all';$('#br').value='all';$('#map-corridor').value='all';filter()};
const storyTerritory=territory;
territory=function(){storyTerritory();let ch=charts.map;if(!ch)return;let u=$('#uf').value,b=$('#br').value,uf=u==='all'?null:REGISTROS.cats.uf[+u],layer=$('#map-layer').value,roads=RODOVIAS.filter(r=>(!uf||r.uf===uf)&&(b==='all'||r.br===+b));$('#map-corridor').value=uf&&b!=='all'?uf+'|'+b:'all';let opt=ch.getOption(),geo=opt.geo[0];geo.label={show:true,fontSize:10,color:'#554b44',textBorderColor:'#fff',textBorderWidth:2};geo.emphasis={label:{show:true,fontSize:12}};geo.zoom=1;geo.center=[-53,-15];if((uf||b!=='all')&&roads.length){let x0=180,x1=-180,y0=90,y1=-90;for(let r of roads)for(let l of r.lines)for(let [x,y]of l){x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y)}geo.center=[(x0+x1)/2,(y0+y1)/2];geo.zoom=Math.min(14,Math.max(1,22/Math.max(x1-x0,y1-y0,1)))}let series=opt.series;
if(layer!=='events'){let line=series[0];line.data=line.data.map(d=>({...d,lineStyle:{...d.lineStyle,width:uf||b!=='all'?3:1.8,opacity:.9}}));let lookup=new Map(roads.map(r=>[r.uf+'|'+r.br,r])),markers=(uf||b!=='all'?roads:[...lookup.values()]);if(markers.length>450)markers=markers.filter((r,i)=>i%Math.ceil(markers.length/450)===0);series=[line,{type:'scatter',coordinateSystem:'geo',symbolSize:uf||b!=='all'?9:6,itemStyle:{color:'#b77a16',borderColor:'#fff',borderWidth:1,opacity:.85},data:markers.map(r=>{let l=r.lines[Math.floor(r.lines.length/2)],c=l[Math.floor(l.length/2)];return{name:r.uf+' · BR-'+String(r.br).padStart(3,'0'),value:c,road:r}})}];}
ch.setOption({geo,series,tooltip:{trigger:'item',confine:true,formatter:p=>{if(p.data?.road){let r=p.data.road;return `<b>${esc(p.name)}</b><br>SNV ${esc(r.code)}<br>km ${N(r.km[0],1)}–${N(r.km[1],1)}<br>${esc(r.admin)}<br>Referência cadastral: 2026<br>Clique para fixar a identificação`};if(p.seriesType==='lines')return `<b>${esc(p.name)}</b><br>${esc(p.data.admin)}<br>${layer==='network'||layer==='admin'?'Geometria SNV 2026; não é taxa de risco':N(p.data.value||0)+' registros do desfecho no recorte'}`;return `<b>${esc(p.name)}</b><br>${Array.isArray(p.value)?N(p.value[2]||0):N(p.value||0)} registros do desfecho`;}}});ch.off('click');ch.on('click',p=>{if(p.data?.road){let r=p.data.road;$('#map-selection').innerHTML=`<b>${esc(p.name)} · SNV ${esc(r.code)}</b><p>km ${N(r.km[0],1)}–${N(r.km[1],1)} · ${esc(r.admin)}. Geometria e administração do cadastro 2026.</p>`}else if(p.seriesType==='map')setUF(p.name);else if(p.seriesType==='lines')$('#map-selection').innerHTML='<b>'+esc(p.name)+'</b><p>'+esc(p.data.admin)+'. Cadastro SNV 2026.</p>'});$('#map-selection').innerHTML=`<b>${uf||'Brasil'}${b==='all'?'':' · BR-'+b.padStart(3,'0')}</b><p>${N(roads.length)} segmentos no traçado selecionado. ${layer==='admin'?'Âmbar: concessão cadastral; cinza: demais administrações.':layer==='network'?'Linhas: malha oficial; marcadores âmbar identificam corredores ou segmentos.':layer==='events'?'Pontos: até 180 intervalos com maior contagem; cores de UF: totais registrados.':'Vermelho: desfecho presente no recorte; cinza: sem desfecho associado.'} Use o seletor para aproximar, a roda do mouse para zoom e clique em um marcador para fixar a identificação.</p>`;};
$('#map-layer').onchange=territory;$('#map-metric').onchange=territory;
function multinomialView(){if(!window.MULTINOMIAL){$('#multi-reading').textContent='A análise multinomial está sendo processada nesta edição local.';return}let outcome=$('#multi-outcome').value,ts=MULTINOMIAL.terms.filter(t=>t.outcome===outcome&&(Object.hasOwn(terms,t.term)||t.term.startsWith('Tipo:'))),v=MULTINOMIAL.validation;$('#multi-terms').innerHTML='<thead><tr><th>Fator</th><th>RRR</th><th>IC 95%</th><th>Leitura do intervalo</th></tr></thead><tbody>'+ts.map(t=>`<tr><td>${esc(terms[t.term]||t.term)}</td><td>${N(t.rrr,2)}</td><td>${N(t.low,2)}–${N(t.high,2)}</td><td>${t.low<=1&&t.high>=1?'Compatível com ausência de associação na escala do modelo':t.low>1?'Razão maior versus sem vítimas':'Razão menor versus sem vítimas'}</td></tr>`).join('')+'</tbody>';let night=ts.find(t=>t.term==='noite');$('#multi-reading').innerHTML=`<b>${esc(outcome)} versus sem vítimas</b><p>Para noite, RRR ${N(night.rrr,2)} [${N(night.low,2)}; ${N(night.high,2)}], condicionada aos controles. Trata-se da razão entre P(desfecho)/P(sem vítimas) à noite e de dia, não de um multiplicador do risco de viajar à noite.</p><p>${N(MULTINOMIAL.meta.n)} ocorrências; ${MULTINOMIAL.meta.clusters} grupos UF–BR. Classificação hierárquica: morte prevalece sobre grave; grave sobre leve.</p>`;$('#multi-validation').innerHTML=`<b>Teste temporal: treino 2022–2023, teste 2024–2025</b><p>Log loss: ${N(v.log_loss,3)}; referência constante: ${N(v.baseline_log_loss,3)}. Brier multiclasse: ${N(v.brier_multiclasse,3)}; referência: ${N(v.baseline_brier,3)}. Menor é melhor. <a href="data/multinomial.json" target="_blank">Matriz de confusão, calibração e resultados completos ↗</a>.</p><p>O modelo não identifica a causa do sinistro nem a qualidade da governança. Registros sem vítimas podem ter cobertura distinta, o que afeta a categoria de referência. Há sensibilidade sem tipo de sinistro, documentada no notebook.</p>`;}
$('#multi-outcome').onchange=multinomialView;
